/* GitHub Theme — Tailwind v3 (hsl) */
/* Channel triplets — consume via hsl(var(--token)). See tailwind.config snippet in docs. */

@layer base {
  /* GitHub Theme - Official GitHub brand colors (Primer Design System)  */

  /* Light mode (:root) */
  :root {
    --background: 300 50% 100%;
    --foreground: 210.9 18% 13.52%;
    --card: 211.18 27.25% 97.5%;
    --card-foreground: 210.9 18% 13.52%;
    --popover: 300 50% 100%;
    --popover-foreground: 210.9 18% 13.52%;
    --primary: 130.75 75.85% 26.75%;
    --primary-foreground: 300 50% 100%;
    --secondary: 211.17 22.45% 94.96%;
    --secondary-foreground: 210.95 13.88% 18.33%;
    --muted: 211.18 17.84% 96.18%;
    --muted-foreground: 211.05 7.33% 39.35%;
    --accent: 217.37 73.35% 53.1%;
    --accent-foreground: 300 50% 100%;
    --destructive: 357.22 68.27% 47.65%;
    --destructive-foreground: 300 50% 100%;
    --border: 211.15 10.68% 83.47%;
    --input: 211.18 17.84% 96.18%;
    --ring: 217.37 73.35% 53.1%;
    --chart-1: 130.75 75.85% 26.75%;
    --chart-2: 217.37 73.35% 53.1%;
    --chart-3: 288.89 44.56% 60.59%;
    --chart-4: 15.59 64.24% 62.89%;
    --chart-5: 172.61 99.75% 29.24%;
    --radius: 0.375rem;
    --sidebar: 211.18 17.84% 96.18%;
    --sidebar-foreground: 210.9 18% 13.52%;
    --sidebar-primary: 130.75 75.85% 26.75%;
    --sidebar-primary-foreground: 300 50% 100%;
    --sidebar-accent: 211.17 22.45% 94.96%;
    --sidebar-accent-foreground: 210.95 13.88% 18.33%;
    --sidebar-border: 211.15 10.68% 83.47%;
    --sidebar-ring: 217.37 73.35% 53.1%;
    --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", "Noto Sans", Helvetica, Arial, sans-serif;
    --font-serif: ui-serif, Georgia, serif;
    --font-mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
    --shadow-color: 215 20% 20%;
    --shadow-opacity: 0.06;
    --shadow-blur: 3px;
    --shadow-spread: 0px;
    --shadow-offset-x: 0;
    --shadow-offset-y: 1px;
    --letter-spacing: -0.01em;
    --spacing: 0.25rem;
    --shadow-2xs: 0 1px 0 0px hsl(215 20% 20% / 0.04);
    --shadow-xs: 0 1px 0 0px hsl(215 20% 20% / 0.04), 0 1px 3px 0px hsl(215 20% 20% / 0.06);
    --shadow-sm: 0 1px 0 0px hsl(215 20% 20% / 0.04), 0 2px 4px 0px hsl(215 20% 20% / 0.08);
    --shadow: 0 1px 0 0px hsl(215 20% 20% / 0.04), 0 2px 4px 0px hsl(215 20% 20% / 0.08);
    --shadow-md: 0 1px 0 0px hsl(215 20% 20% / 0.04), 0 4px 8px 0px hsl(215 20% 20% / 0.1);
    --shadow-lg: 0 1px 0 0px hsl(215 20% 20% / 0.04), 0 8px 16px 0px hsl(215 20% 20% / 0.1);
    --shadow-xl: 0 1px 0 0px hsl(215 20% 20% / 0.04), 0 12px 28px 0px hsl(215 20% 20% / 0.12);
    --shadow-2xl: 0 24px 48px 0px hsl(215 20% 20% / 0.2);
    --tracking-normal: -0.01em;
  }

  /* Dark mode - #0D1117 is GitHub's signature dark background */
  .dark {
    --background: 211.54 36.25% 4.63%;
    --foreground: 211.13 11.55% 81%;
    --card: 210.87 25.16% 7.14%;
    --card-foreground: 211.13 11.55% 81%;
    --popover: 210.9 20.71% 8.89%;
    --popover-foreground: 211.13 11.55% 81%;
    --primary: 127.18 54.77% 34.24%;
    --primary-foreground: 300 50% 100%;
    --secondary: 210.93 17.63% 10.69%;
    --secondary-foreground: 211.13 8.55% 74.71%;
    --muted: 210.95 17.31% 8.85%;
    --muted-foreground: 211.09 4.96% 48.32%;
    --accent: 217.37 73.35% 53.1%;
    --accent-foreground: 300 50% 100%;
    --destructive: 0.76 64.18% 55.69%;
    --destructive-foreground: 300 50% 100%;
    --border: 211.03 9.3% 18.21%;
    --input: 210.87 25.16% 7.14%;
    --ring: 217.37 73.35% 53.1%;
    --chart-1: 127.18 54.77% 34.24%;
    --chart-2: 217.37 73.35% 53.1%;
    --chart-3: 288.86 49.55% 66.65%;
    --chart-4: 15.56 78.71% 69.2%;
    --chart-5: 172.68 99.92% 32.58%;
    --radius: 0.375rem;
    --sidebar: 214.13 37.62% 3.13%;
    --sidebar-foreground: 211.13 11.55% 81%;
    --sidebar-primary: 127.18 54.77% 34.24%;
    --sidebar-primary-foreground: 300 50% 100%;
    --sidebar-accent: 210.93 17.63% 10.69%;
    --sidebar-accent-foreground: 211.13 8.55% 74.71%;
    --sidebar-border: 211.03 9.3% 18.21%;
    --sidebar-ring: 217.37 73.35% 53.1%;
    --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", "Noto Sans", Helvetica, Arial, sans-serif;
    --font-serif: ui-serif, Georgia, serif;
    --font-mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
    --shadow-color: 0 0% 0%;
    --shadow-opacity: 0.4;
    --shadow-blur: 3px;
    --shadow-spread: 0px;
    --shadow-offset-x: 0;
    --shadow-offset-y: 1px;
    --letter-spacing: -0.01em;
    --spacing: 0.25rem;
    --shadow-2xs: 0 0 0 1px hsl(0 0% 0% / 0.3);
    --shadow-xs: 0 0 0 1px hsl(0 0% 0% / 0.3), 0 1px 3px 0px hsl(0 0% 0% / 0.3);
    --shadow-sm: 0 0 0 1px hsl(0 0% 0% / 0.3), 0 2px 4px 0px hsl(0 0% 0% / 0.4);
    --shadow: 0 0 0 1px hsl(0 0% 0% / 0.3), 0 2px 4px 0px hsl(0 0% 0% / 0.4);
    --shadow-md: 0 0 0 1px hsl(0 0% 0% / 0.3), 0 4px 8px 0px hsl(0 0% 0% / 0.4);
    --shadow-lg: 0 0 0 1px hsl(0 0% 0% / 0.3), 0 8px 16px 0px hsl(0 0% 0% / 0.4);
    --shadow-xl: 0 0 0 1px hsl(0 0% 0% / 0.3), 0 12px 28px 0px hsl(0 0% 0% / 0.5);
    --shadow-2xl: 0 24px 48px 0px hsl(0 0% 0% / 0.6);
  }

}
